const locked = page.getByText(/locked/i).first();
await expect(locked).toBeVisible();
// the locked card content must stack in a column, not lay out in a row
const lockedCard = locked.locator('xpath=ancestor::*[self::section or self::article or self::div][1]');
await expect(lockedCard).toHaveCSS('flex-direction', 'column');

await page.goto('/ops/operations');
